import { styleText } from 'node:util';
import { Command } from '@oclif/core';
import { exitCodes } from '@sanity/cli-core';
import { ReaderModelAcknowledgementError, SpawnContractsInvalidError, UnknownProjectRolesError, } from '@sanity/workflow-engine';
import { fail, failureDetail, isAuthRejection } from './fail.js';
import { flagTokens, isLongFlag } from './flags.js';
export class WorkflowCommand extends Command {
    async init() {
        const tokens = flagTokens(this.argv);
        const deprecated = Object.entries(this.ctor.flags ?? {}).flatMap(([name, flag]) => (flag.aliases ?? [])
            .filter((alias) => tokens.some((token) => isLongFlag(token, alias)))
            .map((alias) => ({ alias, name })));
        deprecated.forEach(({ alias, name }) => {
            this.warn(`The --${alias} flag is deprecated and will be removed. Use --${name} instead; keep the same partition value.`);
        });
        await super.init();
    }
    async catch(err) {
        if (err.name === 'ExitPromptError' || err.message === 'SIGINT') {
            this.logToStderr(`${styleText('yellow', '›')} Aborted by user`);
            return this.exit(exitCodes.SIGINT);
        }
        if (isAuthRejection(err)) {
            fail('Authentication failed:', failureDetail(err));
        }
        if (err instanceof ReaderModelAcknowledgementError) {
            fail('Reader-floor acknowledgement:', err.message);
        }
        if (err instanceof UnknownProjectRolesError || err instanceof SpawnContractsInvalidError) {
            fail('Definitions rejected:', err.message);
        }
        return super.catch(err);
    }
}
